import os,sys,pty,select,time
argv=sys.argv[1:]
pid,fd=pty.fork()
if pid==0:
    os.execv(argv[0],argv)
out=b''; t0=time.time(); sent=False
while True:
    if time.time()-t0>8:
        out+=b'<<TIMEOUT>>'; os.kill(pid,9); break
    r,_,_=select.select([fd],[],[],0.3)
    if r:
        try: d=os.read(fd,65536)
        except OSError: break
        if not d: break
        out+=d
    elif not sent and time.time()-t0>2:
        os.write(fd,b'\x04'); sent=True   # EOF
try:
    _,status=os.waitpid(pid,0)
    code=os.waitstatus_to_exitcode(status)
except Exception as e:
    code=repr(e)
print("PTY:",repr(out[:1200]))
print("exit:",code)
